import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;

  const root = new Group();
  root.userData.handlers = {};

  // Store resources for cleanup
  let loadedScene = null;
  const timelines = [];

  // Load GLB mesh
  if (config && config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      loadedScene = gltf.scene;
      root.add(loadedScene);
    });
  }

  // Hover lift (rise‑in) effect
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(root.position, {
    y: '+=0.15',
    duration: 0.3,
    ease: 'power3.out',
  });
  timelines.push(hoverTimeline);

  // Click emit & press‑down effect
  const clickHandler = () => {
    // Emit navigation/event
    ctx.emit('hub-home.select', {});

    // Press‑down animation
    const pressTL = gsap.timeline();
    pressTL
      .to(
        root.scale,
        { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' },
        0
      )
      .to(
        root.scale,
        { x: 1, y: 1, z: 1, duration: 0.12, ease: 'power2.out' },
        0.12
      );
    timelines.push(pressTL);
  };

  // Expose handlers
  root.userData.handlers.hover = (enter) => {
    if (enter) {
      hoverTimeline.play();
    } else {
      hoverTimeline.reverse();
    }
  };
  root.userData.handlers.click = clickHandler;

  // Cleanup routine
  root.userData.cleanup = () => {
    // Kill all GSAP timelines
    timelines.forEach((tl) => tl.kill());

    // Dispose loaded GLTF resources
    if (loadedScene) {
      loadedScene.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          const material = child.material;
          if (Array.isArray(material)) {
            material.forEach((m) => m && m.dispose && m.dispose());
          } else if (material && material.dispose) {
            material.dispose();
          }
        }
      });
    }
  };

  return root;
}
